ALTER TABLE "Registrations" ADD CONSTRAINT "FK_Registrations_AgeCategories_AgeCategoryId" FOREIGN KEY ("AgeCategoryId") REFERENCES "AgeCategories" ("Id") ON DELETE SET NULL;
